-- Question 7

-- Sales leadership wants performance rolled up the org chart. For every employee, compute the total completed order value generated by their whole team
-- that is, themselves plus everyone reporting under them at any depth. A Sales Rep's team is just themselves; a manager's is their entire subtree. 
-- Required output: employee_id, employee_name, role, team_total_revenue.

WITH base_level AS
(
SELECT
		a.employee_id AS base_id,
		a.employee_id AS member_id
FROM dim_employee AS a

UNION ALL

SELECT 
		b.base_id,
		a.employee_id AS member_id
FROM dim_employee AS a
INNER JOIN base_level AS b
ON a.manager_id = b.member_id
),

order_summary AS
(
SELECT 
		sales_rep_id,
		SUM(order_total) AS total_sales
FROM fact_orders
WHERE order_status = 'Completed'
GROUP BY sales_rep_id
)

SELECT 
		a.employee_id, a.employee_name,
		a.role, 
		CAST(SUM(c.total_sales) AS DECIMAL(12,2)) AS team_total_revenue
FROM dim_employee AS a
INNER JOIN base_level AS b
ON a.employee_id = b.base_id
LEFT JOIN order_summary AS c
ON b.member_id = c.sales_rep_id
GROUP BY a.employee_id, a.employee_name, a.role
ORDER BY a.employee_id
OPTION (MAXRECURSION 100);

-- RESULT WRITE UP

-- Calculated the total completed order revenue for each employee, including contributions from all direct and indirect reporting team members across the organizational hierarchy.
-- This provides Sales Leadership with a consolidated view of team-level revenue performance, helping them evaluate team contributions, compare performance across reporting levels,
-- and identify opportunities for improvement.